add_filter( 'woocommerce_cart_contents_count', 'perfectpixel_exclude_hidden_from_cart_count' );

function perfectpixel_exclude_hidden_from_cart_count( $count ) {
	if ( ! WC()->cart ) {
		return $count;
	}
	foreach ( WC()->cart->get_cart() as $item ) {
		$product = wc_get_product( $item['product_id'] );
		if ( $product && 'hidden' === $product->get_catalog_visibility() ) {
			$count -= (int) $item['quantity'];
		}
	}
	return max( 0, $count );
}
